package review.mysql;

import review.mobile.GeminiShutdown;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import java.util.*;

/** A separate test-runtime schema policy. Never expands IntegrationSchema.TABLES. */
public final class DualLedgerProfile {
 public static final String MODE="MYSQL_DUAL_LEDGER_FAKEWIRE",BASE="mysql-dual-ledger-approvals",MODEL="gemini-dual-ledger-mock";
 public static final int PORT=8105;
 public static final List<String> LEDGERS=List.of("study_log_requests","ai_generation_requests");
 public static final List<String> TABLES=java.util.stream.Stream.concat(IntegrationSchema.TABLES.stream(),LEDGERS.stream()).toList();
 public static final Map<String,Set<String>> RIGHTS;
 // Both ledgers lock users with FOR UPDATE; MySQL 8 needs more than SELECT/INSERT.
 static{var r=new LinkedHashMap<String,Set<String>>();for(String t:TABLES)r.put(t,Set.of("SELECT","INSERT"));r.put("study_questions",Set.of("SELECT"));for(String t:List.of("users","study_saved_plans","study_schedule_settings","study_log_requests","ai_generation_requests"))r.put(t,Set.of("SELECT","INSERT","UPDATE"));r.put("integration_run_state",Set.of("SELECT","UPDATE"));RIGHTS=Collections.unmodifiableMap(r);}
 public static String name(String id){return "ai_study_planner_dual_"+IntegrationSchema.id(id).replace("-","");}
 public static String account(String id){return "ai_dl_"+IntegrationSchema.id(id).replace("-","").substring(0,12);}
 public static void port(int p){if(p!=PORT)throw new IllegalArgumentException("Dedicated dual-ledger port8105 required");}
 public static String url(String id){return IntegrationSchema.url(id).replace(IntegrationSchema.name(id),name(id));}
 public static String draft(String file)throws Exception{if(!Set.of("study-log-idempotency.mysql.review.sql","ai-cost-protection.mysql.review.sql").contains(file))throw new IllegalArgumentException();try(var in=Objects.requireNonNull(DualLedgerProfile.class.getResourceAsStream("/review/mysql/dual/"+file))){return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}
 public static String ddl(String id)throws Exception{return "-- REVIEW ONLY. New independent3307 schema; stop on any error.\nCREATE DATABASE `"+name(id)+"` CHARACTER SET utf8mb4;\nUSE `"+name(id)+"`;\n"+IntegrationSchema.tablesSql()+"\n"+draft("study-log-idempotency.mysql.review.sql").replace("__APPROVED_SCHEMA__",name(id))+"\n"+draft("ai-cost-protection.mysql.review.sql").replace("__APPROVED_SCHEMA__",name(id))+"\nINSERT INTO integration_run_state(run_id,state) VALUES('"+IntegrationSchema.id(id)+"','PREPARED');\n";}
 public static List<String> statements(String sql){return Arrays.stream(sql.replaceAll("(?m)^--.*$","").split(";")).map(String::trim).filter(s->!s.isBlank()).toList();}
 public static String grants(String id){var b=new StringBuilder("-- Account is created by the separately approved secure admin action. No password in this file.\n");RIGHTS.forEach((t,p)->b.append("GRANT ").append(String.join(", ",new TreeSet<>(p))).append(" ON `").append(name(id)).append("`.`").append(t).append("` TO '").append(account(id)).append("'@'localhost';\n"));return b.toString();}
 public static void verifyGrants(List<String> lines,String id){var seen=new HashSet<String>();for(String raw:lines){String s=raw.replace("`","");if(s.toUpperCase(Locale.ROOT).contains("WITH GRANT OPTION"))throw new IllegalStateException("Grant delegation forbidden");if(s.matches("GRANT USAGE ON \\*\\.\\* TO .*"))continue;var m=java.util.regex.Pattern.compile("^GRANT ([A-Z, ]+) ON "+name(id)+"\\.([a-z_]+) TO .*$").matcher(s);if(!m.matches()||!RIGHTS.containsKey(m.group(2))||!new HashSet<>(Arrays.asList(m.group(1).split(", "))).equals(RIGHTS.get(m.group(2))))throw new IllegalStateException("Unapproved grant/role/delegation");if(!seen.add(m.group(2)))throw new IllegalStateException("Duplicate grant");}if(!seen.equals(new HashSet<>(TABLES)))throw new IllegalStateException("Exact table grants missing");}
 public static Connection offlineH2(String url,String id)throws Exception{
  if(!url.equals("jdbc:h2:mem:dual_"+IntegrationSchema.id(id)+";MODE=MySQL;DB_CLOSE_DELAY=-1"))throw new IllegalArgumentException("Memory H2 only");
  String sql=IntegrationSchema.tablesSql()+draft("study-log-idempotency.mysql.review.sql")+draft("ai-cost-protection.mysql.review.sql");
  sql=sql.replace("`__APPROVED_SCHEMA__`.","").replace("`","").replace(" CHARACTER SET ascii COLLATE ascii_bin","").replace(" ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","").replace(" ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4","");
  var c=DriverManager.getConnection(url,"sa","");try{if(!c.getMetaData().getDriverName().equals("H2 JDBC Driver"))throw new IllegalStateException();for(String s:statements(sql))try(var p=c.createStatement()){p.execute(s);}try(var p=c.prepareStatement("INSERT INTO integration_run_state VALUES(?,'PREPARED')")){p.setString(1,id);p.executeUpdate();}return c;}catch(Exception failure){c.close();throw failure;}
 }
 public static void verifyMySql(Connection c,String id,boolean empty)throws Exception{
  if(!c.getMetaData().getURL().startsWith("jdbc:mysql://127.0.0.1:3307/"+name(id)+"?")||!c.getMetaData().getDriverName().contains("MySQL"))throw new IllegalStateException("Wrong JDBC target");
  try(var s=c.createStatement();var r=s.executeQuery("SELECT DATABASE(),CURRENT_USER(),CURRENT_ROLE(),VERSION()")){if(!r.next()||!name(id).equals(r.getString(1))||!Objects.equals(account(id)+"@localhost",r.getString(2))||!"NONE".equals(r.getString(3))||!r.getString(4).startsWith("8.0."))throw new IllegalStateException("Wrong database/account/roles/version");}
  try(var s=c.createStatement();var r=s.executeQuery("SHOW SESSION STATUS LIKE 'Ssl_cipher'")){if(!r.next()||r.getString(2).isBlank())throw new IllegalStateException("TLS absent");}
  try(var s=c.createStatement();var r=s.executeQuery("SELECT @@mandatory_roles")){if(!r.next()||!r.getString(1).isBlank())throw new IllegalStateException("Mandatory roles require review");}
  var grants=new ArrayList<String>();try(var s=c.createStatement();var r=s.executeQuery("SHOW GRANTS")){while(r.next())grants.add(r.getString(1));}verifyGrants(grants,id);
  var tables=new HashSet<String>();try(var p=c.prepareStatement("SELECT table_name,engine,table_type FROM information_schema.tables WHERE table_schema=?")){p.setString(1,name(id));try(var r=p.executeQuery()){while(r.next()){if(!"InnoDB".equals(r.getString(2))||!"BASE TABLE".equals(r.getString(3)))throw new IllegalStateException("Only InnoDB base tables");tables.add(r.getString(1));}}}if(!tables.equals(new HashSet<>(TABLES)))throw new IllegalStateException("Exact12 tables required for dual profile only");
  for(String[] pair:List.of(new String[]{"triggers","trigger_schema"},new String[]{"routines","routine_schema"},new String[]{"events","event_schema"}))try(var p=c.prepareStatement("SELECT COUNT(*) FROM information_schema."+pair[0]+" WHERE "+pair[1]+"=?")){p.setString(1,name(id));try(var r=p.executeQuery()){r.next();if(r.getInt(1)!=0)throw new IllegalStateException("Stored side effect forbidden");}}
  requireUnique(c,id,"study_saved_plans",List.of("user_id","goal_id","plan_date"));requireUnique(c,id,"study_schedule_settings",List.of("user_id","schedule_date"));requireUnique(c,id,"integration_requests",List.of("run_id","request_key"));
  for(String t:TABLES)try(var r=c.getMetaData().getImportedKeys(name(id),null,t)){while(r.next())if(!name(id).equals(r.getString("PKTABLE_CAT")))throw new IllegalStateException("Foreign key escaped schema");}
  requirePk(c,id,"study_log_requests",List.of("user_id","operation","request_key"));requirePk(c,id,"ai_generation_requests",List.of("user_id","feature","request_key"));
  for(String t:LEDGERS){var columns=new TreeSet<String>();try(var r=c.getMetaData().getColumns(name(id),null,t,null)){while(r.next())columns.add(r.getString("COLUMN_NAME"));}var expected=t.equals("study_log_requests")?Set.of("user_id","operation","request_key","goal_id","request_hash","request_state","log_id","response_json","created_at","completed_at"):Set.of("user_id","feature","request_key","goal_id","request_hash","request_state","policy_day","provider","model","dispatch_reserved","provider_response_received","result_stored","ai_response_saved","response_id","prompt_sha256","result_json","usage_json","created_at","dispatch_at","completed_at");if(!columns.equals(expected))throw new IllegalStateException("Ledger columns differ");}
  try(var p=c.prepareStatement("SELECT table_name,column_name,collation_name FROM information_schema.columns WHERE table_schema=? AND table_name IN ('study_log_requests','ai_generation_requests') AND column_name IN ('operation','feature','request_key','request_hash')")){p.setString(1,name(id));int count=0;try(var r=p.executeQuery()){while(r.next()){count++;if(!"ascii_bin".equals(r.getString(3)))throw new IllegalStateException("ASCII binary key comparison required");}}if(count!=6)throw new IllegalStateException("Key collation metadata incomplete");}
  try(var p=c.prepareStatement("SELECT table_name,enforced FROM information_schema.table_constraints WHERE constraint_schema=? AND constraint_type='CHECK' AND table_name IN ('study_log_requests','ai_generation_requests')")){p.setString(1,name(id));var checked=new HashSet<String>();try(var r=p.executeQuery()){while(r.next()){if(!"YES".equals(r.getString(2)))throw new IllegalStateException("CHECK must be enforced");checked.add(r.getString(1));}}if(!checked.equals(new HashSet<>(LEDGERS)))throw new IllegalStateException("Ledger CHECK constraints missing");}
  if(empty)for(String t:TABLES)if(!t.equals("integration_run_state"))try(var s=c.createStatement();var r=s.executeQuery("SELECT COUNT(*) FROM "+t)){r.next();if(r.getLong(1)!=0)throw new IllegalStateException("New schema must be empty");}
  c.setTransactionIsolation(Connection.TRANSACTION_READ_COMMITTED);if(c.getTransactionIsolation()!=Connection.TRANSACTION_READ_COMMITTED)throw new IllegalStateException("Profile session isolation mismatch");
 }
 // Do not pass a dual catalog into the legacy verifier or expand its allowlist.
 static void requireUnique(Connection c,String id,String table,List<String> expected)throws Exception{var indexes=new HashMap<String,SortedMap<Integer,String>>();try(var r=c.getMetaData().getIndexInfo(name(id),null,table,true,false)){while(r.next()){String n=r.getString("INDEX_NAME"),column=r.getString("COLUMN_NAME");if(n!=null&&column!=null)indexes.computeIfAbsent(n,k->new TreeMap<>()).put(r.getInt("ORDINAL_POSITION"),column);}}if(indexes.values().stream().noneMatch(m->new ArrayList<>(m.values()).equals(expected)))throw new IllegalStateException("Required dual-profile unique index missing");}
 static void requirePk(Connection c,String id,String t,List<String> expected)throws Exception{var keys=new TreeMap<Integer,String>();try(var r=c.getMetaData().getPrimaryKeys(name(id),null,t)){while(r.next())keys.put(r.getInt("KEY_SEQ"),r.getString("COLUMN_NAME"));}if(!new ArrayList<>(keys.values()).equals(expected))throw new IllegalStateException("Ledger primary key mismatch");}
 public static Map<String,Object> review(String id)throws Exception{return Map.of("mode",MODE,"schema",name(id),"tables",TABLES,"dbHost","127.0.0.1","dbPort",3307,"httpPort",PORT,"realAiCalls",0,"productionFlags",false,"ddlSha256",GeminiShutdown.sha(ddl(id).getBytes(StandardCharsets.UTF_8)));}
}
